-- Additive HR dataset migration. No drops, only creates/alters/inserts. Run once,
-- by hand, in the Supabase SQL Editor. Generated from src/mock/{people,teams,kudos}.ts:
-- 8 of these people are the same humans as the 8 existing employees (matched by name);
-- their existing team/title/manager_id rows are left untouched, only team_id is backfilled.
-- Everyone else is inserted new, using the mock dataset's kebab-case ids as primary keys.

create table teams (
  id    text primary key,
  name  text not null,
  color text not null
);


alter table employees add column team_id text references teams(id);
alter table employees add column slack_linked boolean not null default true;

update employees set team_id = case team
  when 'Engineering' then 'engineering'
  when 'Design' then 'design'
  when 'Marketing' then 'marketing'
  when 'People Ops' then 'people-ops'
  when 'Support' then 'support'
end;

-- 39 net-new employees (the 8 overlapping with real employees are left untouched above)

-- 187 historical kudos rows
